const body = $json.body ?? $json;
const p = body.properties ?? body;
const read = (...keys) => keys.map((key) => body[key] ?? p[key]).find((value) => value !== undefined && value !== null && value !== '');

const required = {
  source_deal_id: read('source_deal_id', 'objectId', 'dealId', 'hs_object_id'),
  company_name: read('company_name', 'companyName', 'company'),
  primary_contact_name: read('primary_contact_name', 'contactName'),
  primary_contact_email: read('primary_contact_email', 'contactEmail', 'email'),
  deal_name: read('deal_name', 'dealname', 'dealName'),
  owner_name: read('owner_name', 'ownerName'),
  owner_email: read('owner_email', 'ownerEmail')
};

const missing = Object.entries(required).filter(([, value]) => !value).map(([key]) => key);
if (missing.length) throw new Error(`Invalid closed-won payload. Missing: ${missing.join(', ')}`);

const stage = read('dealstage', 'stage');
if (stage && !['closedwon', 'closed_won', 'won'].includes(String(stage).toLowerCase())) {
  throw new Error(`Deal stage is not closed-won: ${stage}`);
}

const rawClosedAt = read('closed_won_at', 'closedate', 'closedAt') ?? new Date().toISOString();
const closedAt = /^\d+$/.test(String(rawClosedAt)) ? new Date(Number(rawClosedAt)).toISOString() : new Date(rawClosedAt).toISOString();
const amount = Number(read('amount') ?? 0);
const valueCents = Number(read('value_cents') ?? Math.round(amount * 100));
if (!Number.isFinite(valueCents) || valueCents < 0) throw new Error('Deal value must be a non-negative number');

const normalized = {
  event_id: String(read('event_id', 'eventId', 'subscriptionId') ?? `${required.source_deal_id}:${closedAt}`),
  ...required,
  website: String(read('website') ?? ''),
  value_cents: valueCents,
  currency: String(read('currency') ?? 'USD').toUpperCase(),
  service_template_key: String(read('service_template_key', 'serviceTemplate') ?? 'agency-growth'),
  closed_won_at: closedAt,
  sla_hours: Number(read('sla_hours') ?? 72)
};

return [{ json: { ...normalized, payload_base64: Buffer.from(JSON.stringify(normalized)).toString('base64') } }];
